/** 线性图标颜色前缀：分组图标值以 sp: 开头时表示线性图标 */
const SP_LINE_PREFIX = 'sp:';

/** 是否为线性图标值 */
function spIsLineIcon(v) {
  return typeof v === 'string' && v.indexOf(SP_LINE_PREFIX) === 0;
}

/** 取线性图标 id */
function spLineIconId(v) {
  return spIsLineIcon(v) ? v.slice(SP_LINE_PREFIX.length) : '';
}

/** 渲染线性图标 SVG（currentColor 跟随主题） */
function spLineIconSvg(id, cls) {
  const body = SP_LINE_ICON_PATHS[id];
  if (!body) return '';
  return '<svg class="' + (cls || 'sp-li') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + body + '</svg>';
}

/** 分组图标值 → HTML（emoji 转义文本 / sp: 渲染 SVG） */
function spGroupIconHtml(v) {
  if (!v) return '';
  if (spIsLineIcon(v)) return spLineIconSvg(spLineIconId(v), 'sp-li g-sp-li');
  return String(v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/** 分组图标值 → 纯文本（用于 select / 标题等不能放 SVG 的场景） */
function spGroupIconText(v) {
  if (!v) return '';
  if (spIsLineIcon(v)) {
    const it = SP_LINE_ICONS.find(x => x.i === spLineIconId(v));
    return it ? '▦' : '';
  }
  return String(v);
}
